import{_ as i,o as t,c as r,ae as l}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"Encrypted Credential Store and Lifecycle","description":"","frontmatter":{"work_package_id":"WP01","title":"Encrypted Credential Store and Lifecycle","lane":"done","dependencies":[],"base_branch":"main","base_commit":"052223c7b89f74b50477c7d7de87deeb43505ccf","created_at":"2026-02-27T10:27:28.911589+00:00","subtasks":["T001","T002","T003","T004","T005"],"phase":"Phase 0 - Foundation","assignee":"","agent":"claude-opus","shell_pid":"77167","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/028-secrets-management-and-redaction/tasks/WP01-encrypted-credential-store-and-lifecycle.md","filePath":"specs/028-secrets-management-and-redaction/tasks/WP01-encrypted-credential-store-and-lifecycle.md"}'),s={name:"specs/028-secrets-management-and-redaction/tasks/WP01-encrypted-credential-store-and-lifecycle.md"};function o(a,e,n,c,d,p){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="work-package-prompt-wp01-encrypted-credential-store-and-lifecycle" tabindex="-1">Work Package Prompt: WP01 - Encrypted Credential Store and Lifecycle <a class="header-anchor" href="#work-package-prompt-wp01-encrypted-credential-store-and-lifecycle" aria-label="Permalink to &quot;Work Package Prompt: WP01 - Encrypted Credential Store and Lifecycle&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Implement AES-256-GCM encryption with master key derived from the OS keychain.</li><li>Deliver a per-provider+workspace scoped credential store encrypted at rest on local filesystem.</li><li>Implement credential lifecycle: create, rotate (irrecoverable overwrite), and revoke with audit events.</li><li>Enforce cross-provider credential isolation preventing access across provider boundaries.</li></ul><p>Success criteria:</p><ul><li>Stored credentials are encrypted on disk; raw values never appear in plaintext files.</li><li>Credential rotation overwrites previous value irrecoverably (SC-028-002).</li><li>Cross-provider credential access is denied in 100% of isolation tests (SC-028-004).</li><li>Every credential lifecycle action produces an audit event with correlation ID.</li><li>Credential operations complete in &lt; 50ms.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/028-secrets-management-and-redaction/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/028-secrets-management-and-redaction/spec.md</code></li><li>Protocol bus: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/protocol/bus.ts</code></li></ul></li><li>Provider isolation (spec 025): <ul><li>Credential scoping aligns with provider+workspace boundaries.</li></ul></li></ul><p>Constraints:</p><ul><li>TypeScript + Bun runtime with Node crypto for AES-256-GCM.</li><li>Fully offline; no remote key vault dependency (NFR-028-003).</li><li>AES-256-GCM minimum encryption standard (NFR-028-002).</li><li>Coverage &gt;=85% with FR-028-001, FR-028-002, FR-028-003 traceability.</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP01</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t001-implement-aes-256-gcm-encryption-module-with-os-keychain-master-key" tabindex="-1">Subtask T001 - Implement AES-256-GCM encryption module with OS keychain master key <a class="header-anchor" href="#subtask-t001-implement-aes-256-gcm-encryption-module-with-os-keychain-master-key" aria-label="Permalink to &quot;Subtask T001 - Implement AES-256-GCM encryption module with OS keychain master key&quot;">​</a></h3><ul><li>Purpose: Provide the cryptographic foundation for credential storage.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/secrets/encryption.ts</code>.</li><li>Implement <code>EncryptionService</code> class: <ul><li><code>encrypt(plaintext: string): Promise&lt;EncryptedPayload&gt;</code>: <ul><li>Generate random 12-byte IV per encryption.</li><li>Encrypt using AES-256-GCM with master key and IV.</li><li>Return <code>{ ciphertext: Buffer, iv: Buffer, authTag: Buffer }</code>.</li></ul></li><li><code>decrypt(payload: EncryptedPayload): Promise&lt;string&gt;</code>: <ul><li>Decrypt using master key, IV, and auth tag.</li><li>Verify auth tag (GCM does this automatically; invalid tag throws).</li><li>Return plaintext string.</li></ul></li><li><code>getMasterKey(): Promise&lt;Buffer&gt;</code>: <ul><li>Retrieve master key from OS keychain.</li><li>If no key exists, generate 256-bit random key and store in keychain.</li><li>Cache key in memory for session duration (avoid repeated keychain calls).</li></ul></li></ul></li><li>Define <code>EncryptedPayload</code> type: <code>{ ciphertext: Buffer, iv: Buffer, authTag: Buffer, version: number }</code>.</li><li>Implement OS keychain abstraction: <ul><li>Interface: <code>KeychainProvider { get(service: string, account: string): Promise&lt;Buffer | null&gt;, set(service: string, account: string, key: Buffer): Promise&lt;void&gt; }</code>.</li><li>macOS implementation using <code>security</code> CLI or keychain API.</li><li>Fallback: file-based key storage with restrictive permissions (0600) for platforms without keychain.</li></ul></li><li>Key derivation: use HKDF to derive per-provider keys from master key + provider ID salt.</li><li>Ensure no plaintext key material is logged or exposed in error messages.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/secrets/encryption.ts</code></li></ul></li><li>Validation: <ul><li>Encrypt/decrypt round-trip produces original plaintext.</li><li>Different IVs produce different ciphertexts for same plaintext.</li><li>Tampered ciphertext or auth tag causes decryption failure.</li><li>Master key is retrieved from keychain (or generated on first use).</li><li>Per-provider key derivation produces different keys for different providers.</li><li>No plaintext key material in logs or errors.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t002-implement-per-provider-workspace-credential-store" tabindex="-1">Subtask T002 - Implement per-provider+workspace credential store <a class="header-anchor" href="#subtask-t002-implement-per-provider-workspace-credential-store" aria-label="Permalink to &quot;Subtask T002 - Implement per-provider+workspace credential store&quot;">​</a></h3><ul><li>Purpose: Store credentials securely with provider+workspace scoping.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/secrets/credential-store.ts</code>.</li><li>Implement <code>CredentialStore</code> class: <ul><li><code>store(providerId: string, workspaceId: string, credentialName: string, value: string): Promise&lt;void&gt;</code>: <ul><li>Derive per-provider encryption key using HKDF.</li><li>Encrypt value with provider-specific key.</li><li>Write encrypted payload to filesystem: <code>&lt;data-dir&gt;/secrets/&lt;providerId&gt;/&lt;workspaceId&gt;/&lt;credentialName&gt;.enc</code>.</li><li>Use atomic write (temp + rename) to prevent partial writes.</li></ul></li><li><code>retrieve(providerId: string, workspaceId: string, credentialName: string): Promise&lt;string&gt;</code>: <ul><li>Read encrypted payload from filesystem.</li><li>Decrypt with provider-specific key.</li><li>Return plaintext value.</li></ul></li><li><code>list(providerId: string, workspaceId: string): Promise&lt;string[]&gt;</code>: <ul><li>List credential names for provider+workspace.</li></ul></li><li><code>delete(providerId: string, workspaceId: string, credentialName: string): Promise&lt;void&gt;</code>: <ul><li>Remove credential file from filesystem.</li><li>Overwrite file content with random data before deletion (defense-in-depth).</li></ul></li></ul></li><li>Implement scoped access enforcement: <ul><li>All operations require both providerId and workspaceId.</li><li>Credential paths are deterministic: provider+workspace -&gt; directory path.</li><li>No API to list credentials across providers.</li></ul></li><li>Handle concurrent access: <ul><li>Use file-level locking (advisory locks) for write operations.</li><li>Read operations do not require locks (atomic write ensures consistency).</li></ul></li><li>Ensure credential files have restrictive permissions (0600).</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/secrets/credential-store.ts</code></li></ul></li><li>Validation: <ul><li>Store/retrieve round-trip produces original value.</li><li>Credential file on disk is encrypted (not plaintext).</li><li>File permissions are 0600.</li><li>Concurrent store operations do not corrupt files.</li><li>List returns only credentials for specified provider+workspace.</li><li>Delete overwrites before removal.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t003-implement-credential-lifecycle-operations-with-audit-events" tabindex="-1">Subtask T003 - Implement credential lifecycle operations with audit events <a class="header-anchor" href="#subtask-t003-implement-credential-lifecycle-operations-with-audit-events" aria-label="Permalink to &quot;Subtask T003 - Implement credential lifecycle operations with audit events&quot;">​</a></h3><ul><li>Purpose: Provide create, rotate, and revoke operations with full audit trail.</li><li>Steps: <ol><li>In <code>credential-store.ts</code>, implement lifecycle methods: <ul><li><code>create(providerId: string, workspaceId: string, name: string, value: string, correlationId: string): Promise&lt;void&gt;</code>: <ul><li>Check if credential already exists; reject with error if duplicate.</li><li>Store credential.</li><li>Emit <code>secrets.credential.created</code> bus event with provider ID, workspace ID, credential name (NOT value), correlation ID.</li></ul></li><li><code>rotate(providerId: string, workspaceId: string, name: string, newValue: string, correlationId: string): Promise&lt;void&gt;</code>: <ul><li>Verify credential exists; reject if not found.</li><li>Overwrite with new value (old value irrecoverable after atomic write).</li><li>Emit <code>secrets.credential.rotated</code> bus event.</li></ul></li><li><code>revoke(providerId: string, workspaceId: string, name: string, correlationId: string): Promise&lt;void&gt;</code>: <ul><li>Verify credential exists.</li><li>Delete credential (overwrite + remove).</li><li>Emit <code>secrets.credential.revoked</code> bus event.</li></ul></li></ul></li><li>Implement credential access logging: <ul><li>Every <code>retrieve</code> call emits <code>secrets.credential.accessed</code> bus event with provider ID, workspace ID, credential name, correlation ID.</li><li>Access events are audit-only (do not affect operation).</li></ul></li><li>All bus events pass through audit sink (spec 024) for persistence.</li><li>Never include credential values in bus events, logs, or error messages.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/secrets/credential-store.ts</code></li></ul></li><li>Validation: <ul><li>Create stores credential and emits event.</li><li>Create rejects duplicate.</li><li>Rotate overwrites value irrecoverably.</li><li>Revoke removes credential and emits event.</li><li>Access emits audit event.</li><li>No credential values in any bus event or log.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t004-implement-cross-provider-credential-isolation-enforcement" tabindex="-1">Subtask T004 - Implement cross-provider credential isolation enforcement <a class="header-anchor" href="#subtask-t004-implement-cross-provider-credential-isolation-enforcement" aria-label="Permalink to &quot;Subtask T004 - Implement cross-provider credential isolation enforcement&quot;">​</a></h3><ul><li>Purpose: Prevent credential access across provider boundaries.</li><li>Steps: <ol><li>In <code>credential-store.ts</code>, add isolation enforcement: <ul><li><code>retrieve</code> and <code>list</code> only return credentials for the specified provider+workspace.</li><li>There is no API to query credentials across providers.</li><li>Filesystem path structure enforces isolation: credentials for provider A are in a different directory than provider B.</li></ul></li><li>Implement isolation validation in <code>retrieve</code>: <ul><li>Verify the requesting context&#39;s provider ID matches the credential&#39;s provider ID.</li><li>If mismatch: throw <code>CREDENTIAL_ACCESS_DENIED</code> error.</li><li>Emit <code>secrets.credential.access.denied</code> bus event with attempting provider ID, target provider ID, correlation ID.</li></ul></li><li>Add a <code>CredentialAccessContext</code> type: <ul><li><code>requestingProviderId: string</code>, <code>requestingWorkspaceId: string</code>, <code>correlationId: string</code>.</li><li>Pass context to all credential operations.</li></ul></li><li>Implement directory traversal prevention: <ul><li>Validate provider ID and workspace ID contain no path separators or special characters.</li><li>Reject IDs with <code>..</code>, <code>/</code>, <code>\\</code>, or null bytes.</li></ul></li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/secrets/credential-store.ts</code></li></ul></li><li>Validation: <ul><li>Credential for provider A is not accessible from provider B context.</li><li>Access denial emits bus event.</li><li>Path traversal attempts are rejected.</li><li>No API allows cross-provider credential enumeration.</li></ul></li><li>Parallel: Yes (after T001-T003 are stable).</li></ul><h3 id="subtask-t005-add-unit-tests-for-encryption-credential-store-lifecycle-and-isolation" tabindex="-1">Subtask T005 - Add unit tests for encryption, credential store, lifecycle, and isolation <a class="header-anchor" href="#subtask-t005-add-unit-tests-for-encryption-credential-store-lifecycle-and-isolation" aria-label="Permalink to &quot;Subtask T005 - Add unit tests for encryption, credential store, lifecycle, and isolation&quot;">​</a></h3><ul><li>Purpose: Lock credential security behavior before redaction engine is built.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/secrets/__tests__/</code>.</li><li>Add <code>encryption.test.ts</code>: <ul><li>Test encrypt/decrypt round-trip.</li><li>Test different IVs produce different ciphertexts.</li><li>Test tampered ciphertext throws on decrypt.</li><li>Test tampered auth tag throws on decrypt.</li><li>Test master key generation and keychain storage.</li><li>Test per-provider key derivation produces unique keys.</li><li>Test no plaintext in error messages.</li></ul></li><li>Add <code>credential-store.test.ts</code>: <ul><li>Test store/retrieve round-trip.</li><li>Test file on disk is encrypted.</li><li>Test file permissions are 0600.</li><li>Test create rejects duplicate.</li><li>Test rotate overwrites irrecoverably (store, rotate, verify old value not recoverable from file).</li><li>Test revoke removes file after overwrite.</li><li>Test list returns only matching provider+workspace.</li><li>Test concurrent store operations.</li></ul></li><li>Add <code>credential-lifecycle.test.ts</code>: <ul><li>Test create emits audit event without value.</li><li>Test rotate emits audit event.</li><li>Test revoke emits audit event.</li><li>Test retrieve emits access audit event.</li><li>Test no credential values in any bus event.</li></ul></li><li>Add <code>credential-isolation.test.ts</code> (SC-028-004): <ul><li>Test cross-provider access is denied.</li><li>Test access denial emits bus event.</li><li>Test path traversal rejection (<code>../</code>, <code>/</code>, <code>\\</code>).</li><li>Test null byte injection rejection.</li><li>Test no cross-provider enumeration API.</li></ul></li><li>Map tests to requirements: <ul><li>FR-028-001 (encrypted store): encryption and store tests.</li><li>FR-028-002 (scoped access): isolation tests.</li><li>FR-028-003 (lifecycle): lifecycle tests.</li><li>FR-028-009 (access audit): access event tests.</li></ul></li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/secrets/__tests__/encryption.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/secrets/__tests__/credential-store.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/secrets/__tests__/credential-lifecycle.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/secrets/__tests__/credential-isolation.test.ts</code></li></ul></li><li>Validation: <ul><li>All tests pass.</li><li>Coverage &gt;=85% on encryption.ts and credential-store.ts.</li><li>FR-028-001, FR-028-002, FR-028-003, FR-028-009 each have at least one mapped test.</li></ul></li><li>Parallel: Yes (after T001-T003 are stable).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Use temporary filesystem directories for credential storage tests.</li><li>Mock OS keychain for encryption tests (or use test keychain).</li><li>Bus events captured via test spy.</li><li>Irrecoverability verified by reading raw file bytes after rotation.</li><li>Isolation tests attempt cross-provider access with different context objects.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: OS keychain API not available on all platforms.</li><li>Mitigation: Fallback to file-based key storage with restrictive permissions; keychain abstracted behind interface.</li><li>Risk: File permission enforcement varies by filesystem.</li><li>Mitigation: Verify permissions in tests; warn on non-POSIX filesystems.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm AES-256-GCM is used with random IVs per encryption.</li><li>Confirm master key comes from OS keychain, not hardcoded.</li><li>Confirm per-provider key derivation uses HKDF with provider ID salt.</li><li>Confirm rotation makes old value irrecoverable.</li><li>Confirm no credential values appear in bus events, logs, or errors.</li><li>Confirm cross-provider access is denied with path traversal prevention.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z -- system -- lane=planned -- Prompt created.</li><li>2026-02-27T10:27:29Z – claude-opus – shell_pid=17896 – lane=doing – Assigned agent via workflow command</li><li>2026-02-27T10:35:53Z – claude-opus – shell_pid=17896 – lane=planned – Deferring: starting with foundational spec 019 first</li><li>2026-03-01T12:17:11Z – claude-opus – shell_pid=54433 – lane=doing – Started implementation via workflow command</li><li>2026-03-01T12:24:06Z – claude-opus – shell_pid=54433 – lane=for_review – Encrypted credential store</li><li>2026-03-01T12:31:23Z – claude-opus – shell_pid=77167 – lane=doing – Started review via workflow command</li><li>2026-03-01T12:35:33Z – claude-opus – shell_pid=77167 – lane=done – Review passed: HKDF fixed to use native hkdfSync, path traversal guard hardened with trailing sep, chmodSync static import, secure overwrite documented as best-effort, 54 tests passing</li></ul>',30)])])}const h=i(s,[["render",o]]);export{m as __pageData,h as default};
